begin;
create temp table email_fixture as select id u,(select id from auth.users where id<>a.id limit 1) p from auth.users a limit 1;
create temp table email_ledger_guard as select count(*) n,sum(amount) total from transactions;
grant select on email_fixture to authenticated,service_role;
set local role service_role;
do $$declare f record;s jsonb;c jsonb;blocked boolean;n int;rows jsonb;begin
select * into strict f from email_fixture;
insert into finance_email_oauth_states(state_hash,owner_id,verifier) values('email-fixture',f.u,'fixture-cipher');
blocked:=false;if f.p is not null then begin perform finance_email_claim_state('email-fixture',f.p);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Foreign login claimed OAuth state';end if;end if;s:=finance_email_claim_state('email-fixture',f.u);if (s->>'owner_id')::uuid<>f.u then raise exception 'OAuth owner binding lost';end if;
blocked:=false;begin perform finance_email_claim_state('email-fixture',f.u);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'OAuth state replay accepted';end if;
perform finance_email_connect('email-fixture',f.u,'fixture@example.test','encrypted-fixture');
c:=finance_email_begin_sync(f.u,'after:1 subject:receipt',90,true);
blocked:=false;begin perform finance_email_begin_sync(f.u,'other',90,true);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Concurrent sync accepted';end if;
rows:=jsonb_build_array(jsonb_build_object('message_id','fixture-message','subject','Receipt','sender','Fixture','sent_at',now(),'body_cipher','encrypted-email-fixture'));
n:=finance_email_finish_sync(f.u,(c->>'lease')::uuid,rows,'next-page');if n<>1 then raise exception 'Receipt not saved';end if;
blocked:=false;begin perform finance_email_finish_sync(f.u,(c->>'lease')::uuid,rows,null);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale lease accepted';end if;
c:=finance_email_begin_sync(f.u,'new query',365,false);if c->>'sync_cursor'<>'next-page' or c->>'sync_query'<>'after:1 subject:receipt' then raise exception 'Pagination changed its search scope';end if;
n:=finance_email_finish_sync(f.u,(c->>'lease')::uuid,rows,null);if n<>0 then raise exception 'Duplicate email imported';end if;
delete from finance_email_receipts where owner_id=f.u;
c:=finance_email_begin_sync(f.u,'after:1 subject:receipt',90,true);n:=finance_email_finish_sync(f.u,(c->>'lease')::uuid,rows,null);if n<>0 then raise exception 'Expired email lost duplicate protection';end if;
insert into finance_email_oauth_states(state_hash,owner_id,verifier) values('cancelled-fixture',f.u,'fixture-cipher');
perform finance_email_claim_state('cancelled-fixture',f.u);perform finance_email_disconnect(f.u);
blocked:=false;begin perform finance_email_connect('cancelled-fixture',f.u,'fixture@example.test','fixture');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Cancelled callback reconnected inbox';end if;
if exists(select 1 from finance_email_seen where owner_id=f.u) or exists(select 1 from finance_email_receipts where owner_id=f.u) or exists(select 1 from finance_email_connections where owner_id=f.u) then raise exception 'Disconnect retained private email data';end if;
insert into finance_email_oauth_states(state_hash,owner_id,verifier,expires_at) values('expired-fixture',f.u,'fixture',now()-interval '1 minute');
blocked:=false;begin perform finance_email_claim_state('expired-fixture',f.u);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Expired state accepted';end if;
end;$$;
reset role;set local role authenticated;
do $$declare blocked boolean;f record;begin
select * into strict f from email_fixture;perform set_config('request.jwt.claim.sub',f.u::text,true);
blocked:=false;begin perform credential from finance_email_connections;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Browser read email tokens';end if;
blocked:=false;begin perform body_cipher from finance_email_receipts;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Browser bypassed receipt service';end if;
blocked:=false;begin perform finance_email_disconnect(f.u);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Browser called privileged service RPC';end if;
if f.p is not null then perform set_config('request.jwt.claim.sub',f.p::text,true);blocked:=false;begin perform * from finance_email_seen;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Partner read email identities';end if;end if;
end;$$;
reset role;set local role anon;
do $$declare blocked boolean:=false;begin begin perform * from finance_email_oauth_states;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Anonymous read OAuth flows';end if;end;$$;
reset role;
do $$begin if (select n from email_ledger_guard)<>(select count(*) from transactions) or (select total from email_ledger_guard) is distinct from (select sum(amount) from transactions) then raise exception 'Email sync changed ledger';end if;end;$$;
rollback;
select 'PASS: OAuth owner binding, replay/expiry, cancellation, lease races, pagination, persistent deduplication, private access, disconnect and unchanged ledger; fixtures rolled back' as result;
